const ORD_ST={pendente:['Pendente','#FDEBDD','#A8420A','#F26A1B'],andamento:['Em andamento','#E9E8F8','#4B45B5','#5B55C9'],pausada:['Pausada','#FDF3D0','#6B5000','#D9A514'],concluida:['Concluída','#E1F3E8','#1D6B3E','#2E9A5E']};
