const badge=(t,bg,fg,icn)=>`<span class="badge" style="background:${bg};color:${fg}">${icn?ic(icn,13):'<span class="dot"></span>'}${esc(t)}</span>`;
const bOrd=s=>badge(ORD_ST[s][0],ORD_ST[s][1],ORD_ST[s][2]);
const bOp=s=>badge(OP_ST[s][0],OP_ST[s][1],OP_ST[s][2],OP_ST[s][3]);
const evIgual=(s,f)=>s===f||(f==='PR'&&s==='PRE');
const EV_SIG={PE:'aguardando envio',PER:'reenvio pendente',LE:'aguardando retorno do SAP',PR:'processado pelo SAP',PRE:'processado pelo SAP após reenvio',ER:'erro no SAP'},evTip=s=>'Sigla '+s+': '+EV_SIG[s]+'.';
