function toast(m,err){const t=$('toast');t.textContent=m;t.className='toast show'+(err?' err':'');clearTimeout(t._h);t._h=setTimeout(()=>t.className='toast',3400)}
function csv(nome,cab,linhas){const c=v=>'"'+String(v??'').replace(/"/g,'""')+'"',txt='﻿'+[cab,...linhas].map(l=>l.map(c).join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'text/csv;charset=utf-8'}));a.download=nome+'_'+iso(new Date())+'.csv';document.body.appendChild(a);a.click();a.remove();toast('Arquivo '+a.download+' gerado')}

/* ===== Modal ===== */
let modalBack=null;
function openModal({title,body,actions=[],mw}){closeModal();modalBack=document.activeElement;const s=document.createElement('div');s.className='scrim';s.id='scrim';s.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="mt" style="--mw:${mw||560}px"><div class="m-h"><h3 id="mt">${esc(title)}</h3><button class="ib" data-m="x" aria-label="Fechar">${ic('x',20)}</button></div><div class="m-b">${body}</div><div class="m-f">${actions.map((a,i)=>`<button class="btn ${a.cls||'btn-s'}" data-m="${i}">${esc(a.label)}</button>`).join('')}</div></div>`;
 s.addEventListener('mousedown',e=>{if(e.target===s)closeModal()});
 s.addEventListener('click',e=>{const b=e.target.closest('[data-m]');if(!b)return;if(b.dataset.m==='x')return closeModal();const a=actions[+b.dataset.m];if(!a.fn||a.fn(s)!==false)closeModal()});
 document.body.appendChild(s);(s.querySelector('.m-b input:not([type=checkbox]),.m-b select,.m-b textarea')||s.querySelector('.m-f .btn:last-child')||s.querySelector('[data-m]')).focus()}
function closeModal(){const s=$('scrim');if(s){s.remove();if(modalBack&&modalBack.isConnected)modalBack.focus()}}
function confirmar(title,txt,label,fn,cls){openModal({title,body:`<p>${txt}</p>`,actions:[{label:'Cancelar'},{label,cls:cls||'btn-p',fn}]})}
function valida(root,regras){let ok=true,first=null;regras.forEach(([id,cond])=>{const el=root.querySelector('#'+id),f=el.closest('.fld'),bom=cond(el.value.trim());f.classList.toggle('bad',!bom);if(!bom){ok=false;first=first||el}});if(first)first.focus();return ok}
const fld=(id,label,ctl,err,cls='')=>`<div class="fld ${cls}"><label class="lbl" for="${id}" style="white-space:normal">${label}${err?' <span class="req">*</span>':''}</label>${ctl}${err?`<p class="f-err">${err}</p>`:''}</div>`;
const sel=(id,opts,v,ph)=>`<select class="inp" id="${id}">${ph!==undefined?`<option value="">${esc(ph)}</option>`:''}${opts.map(o=>{const[k,t]=Array.isArray(o)?o:[o,o];return`<option value="${esc(k)}"${k===v?' selected':''}>${esc(t)}</option>`}).join('')}</select>`;
const details=l=>`<div class="details">${l.map(([k,v,w])=>`<div class="${w?'wide':''}"><span>${esc(k)}</span><span>${v===undefined||v===''||v===null?'—':esc(v)}</span></div>`).join('')}</div>`;

