function vDashGeral(){const D=S.dash||(S.dash={dias:30,centro:'',tab:'geral'}),dias=D.dias,inP=d=>d&&(NOW-d)/DAY<=dias,fo=o=>!D.centro||o.centro===D.centro,ords=ORDENS.filter(fo),cods=new Set(ords.map(o=>o.codigo)),conc=ords.filter(o=>o.status==='concluida'&&inP(o.fim)),abertas=ords.filter(o=>inP(o.inicio)),evs=EVENTOS.filter(e=>inP(e.data)&&(e.origem==='nota'||cods.has(e.ref))),nts=NOTAS.filter(n=>inP(n.inicio));
 const hr=conc.flatMap(o=>o.ops),hP=hr.reduce((a,p)=>a+p.dur,0),hR=hr.reduce((a,p)=>a+p.horas,0),procT=evs.filter(e=>['PR','PRE','ER'].includes(e.status)),taxa=procT.length?Math.round(procT.filter(e=>e.status!=='ER').length/procT.length*100):0,tm=conc.length?conc.reduce((a,o)=>a+(o.fim-o.inicio)/36e5,0)/conc.length:0;
 const n=dias===7?7:Math.ceil(dias/7),w=dias===7?1:7,bk=Array.from({length:n},(_,i)=>{const fim=new Date(NOW.getTime()-(n-1-i)*w*DAY);return{fim,ini:new Date(fim.getTime()-w*DAY),l:pad(fim.getDate())+'/'+pad(fim.getMonth()+1)}}),inB=(d,b)=>d&&d>b.ini&&d<=b.fim,labels=bk.map(b=>b.l);
 const sAb=bk.map(b=>ords.filter(o=>inB(o.inicio,b)).length),sEn=bk.map(b=>ords.filter(o=>inB(o.fim,b)).length);
 const grp=[['Aguardando SAP','le','#5B55C9'],['Processados','ok','#2E9A5E'],['Erro no SAP','er','#C8341F']].map(([nm,k,c])=>({n:nm,c,v:bk.map(b=>evs.filter(e=>inB(e.data,b)&&evGrupo(e.status)===k).length)}));
 const back=CTS.map(c=>[c.split(' - ')[1].replace('Aciaria melt shop operação','Aciaria operação'),ords.filter(o=>o.ct===c&&o.status!=='concluida').length]).sort((a,b)=>b[1]-a[1]);
 const tp=['PM01','PM02','PM03','PM05','PM10'].map(t=>[t,abertas.filter(o=>o.tipo===t).length]);
 const mot=MOTIVOS.map(m=>[m,ords.flatMap(o=>o.ops).filter(p=>p.motivo===m&&p.conf.some(c=>inP(c.fim))).length]).sort((a,b)=>b[1]-a[1]);
 const val=(x,y)=>nts.filter(k=>k.prob===x&&k.impacto===y).length;
 const kpi=(v,l,icn,bg,fg)=>`<div class="tile"><span class="ic" style="background:${bg};color:${fg}">${ic(icn,20)}</span><span class="num">${v}</span><span class="lab">${l}</span></div>`;
 return head('dash','Indicadores','Números de ordens, operações, notas e envios ao SAP no período escolhido. Dados de exemplo do protótipo.',`<button class="btn btn-s" data-act="dashCsv">${ic('down')}Exportar</button>`)+
 `<section class="card dash-f"><div class="segs" role="group" aria-label="Período">${[7,30,60,90].map(d=>`<button class="seg${dias===d?' on':''}" data-act="dashD" data-k="${d}" aria-pressed="${dias===d}">${d} dias</button>`).join('')}</div><label class="fld"><span class="lbl">Centro</span><select class="inp" style="width:240px" data-act-ch="dash" data-k="centro"><option value="">Todos</option>${CENTROS.map(c=>`<option${D.centro===c?' selected':''}>${esc(c)}</option>`).join('')}</select></label></section>
 <section class="tiles">${kpi(conc.length,'Ordens encerradas','flag','#E1F3E8','#1D6B3E')}${kpi(tm.toFixed(1).replace('.',',')+' h','Tempo médio até o encerramento','clock','#E9E8F8','#5B55C9')}${kpi(hR.toFixed(0)+' / '+hP.toFixed(0)+' h','Horas realizadas / planejadas','layers','#FDEBDD','#D35A12')}${kpi(taxa+'%','Envios ao SAP sem erro','check','#DDF0F2','#1A7A85')}</section>
 <div class="charts">
 ${card('a','Ordens abertas e encerradas',dias===7?'Por dia':'Por semana, data final no eixo',line(labels,[{n:'Abertas',c:CH.o,v:sAb},{n:'Encerradas',c:CH.i,v:sEn}],'Ordens'),[['Período','Abertas','Encerradas'],...labels.map((l,i)=>[l,sAb[i],sEn[i]])],leg([['Abertas',CH.o],['Encerradas',CH.i]]))}
 ${card('b','Envios ao SAP por status',dias===7?'Por dia':'Por semana, data final no eixo',vstack(labels,grp,'Envios'),[['Período',...grp.map(g=>g.n)],...labels.map((l,i)=>[l,...grp.map(g=>g.v[i])])],leg(grp.map(g=>[g.n,g.c])))}
 ${card('c','Ordens em aberto por centro de trabalho','Ordens abertas hoje (pendentes, em andamento e pausadas)',hbar(back,CH.o,['ordem','ordens']),[['Centro de trabalho','Ordens'],...back])}
 ${card('d','Ordens por tipo','Ordens iniciadas no período',hbar(tp,CH.o,['ordem','ordens']),[['Tipo','Ordens'],...tp])}
 ${card('e','Motivos de desvio','Operações confirmadas com desvio no período',hbar(mot,CH.o,['operação','operações']),[['Motivo','Operações'],...mot])}
 ${card('f','Notas por probabilidade e impacto','Quantidade de notas no período. Quanto mais escuro, mais notas.',heat(PROBS,IMPACTOS,val),[['Impacto',...PROBS],...IMPACTOS.map(y=>[y,...PROBS.map(x=>val(x,y))])])}
 </div>`}

