/* Telas */
function vSaude(){const T=S.sa||(S.sa={tab:'dia',dt:'usuarios',q:'',f1:'',f2:'',f3:''});
 return head('pulse','Saúde da aplicação','Rotina diária que verifica se o Mobilidade está funcionando de ponta a ponta: filas, banco, envio de ordens e retornos aos aparelhos e login.',`<span class="pill">${ic('clock',14)}Rotina de ${fd(NOW)} às ${AGENDA.hora}</span>`)+tabsH([['dia','Saúde do dia'],['despacho','Despacho'],['historico','Histórico'],['agenda','Agendamento e e-mail']],T.tab,'saTab')+(T.tab==='dia'?saDia():T.tab==='despacho'?saDespacho(T):T.tab==='agenda'?saAgenda():saHistorico())}
function qRows(rows){return rows.map(([l,v,i,p])=>`<div class="q-row"><span>${esc(l)} ${infoI(i)}</span><b>${nf(v)}${p?` <em>${p}</em>`:''}</b></div>`).join('')}
function qBars(t,l,cor,info){const mx=Math.max(1,...l.map(x=>x[1]));return`<div class="q-sec">${t} ${infoI(info)}</div>`+l.map(([lab,v])=>`<div class="q-bar"><div><span>${esc(lab)}</span><b>${nf(v)}</b></div><span class="bar"><i style="width:${v/mx*100}%;background:${cor}"></i></span></div>`).join('')}
function qCard(q){const m=q.main,mainH=`<div class="q-main">${m.ring!==undefined?ring(m.ring,ringC(m.ring)):''}<div><span class="q-big">${m.v}</span><span class="q-lab">${esc(m.l)} ${infoI(m.i)}</span></div></div>`;
 return`<section class="card q-card${q.wide?' wide':''}"><div class="q-head"><span class="q-n">${q.n}</span><h2>${esc(q.t)}</h2><span title="${esc(q.regra)}">${bSa(q.st)}</span></div>${mainH}
 ${q.wide?`<div class="q-cols"><div><div class="q-sec">Números</div>${qRows(q.rows)}</div><div>${qBars('Por motivo do usuário',q.barsU,'#E8641A','Pendências que dependem do usuário ou do planejamento. Não são falha do sistema.')}${qBars('Com o sistema (TI)',q.barsT,'#8B8FA6','Pendências por falha técnica. Tratar com a TI.')}</div></div>`:qRows(q.rows)}
 <div class="q-foot"><button class="link" data-act="saDet" data-k="${q.det}">Detalhes →</button></div></section>`}
