function saTabela(T){const q=T.q.toLowerCase(),m=(o)=>!q||Object.values(o).some(v=>String(v instanceof Date?fdt(v):v??'').toLowerCase().includes(q)),dg=can('diag');
 const uCell=(id,nome)=>`<span style="min-width:0"><b class="clip" style="display:block;font-weight:600">${apMat(id)&&dg?`<button class="link" data-act="diagU" data-k="${id}">${esc(id)}</button>`:esc(id)}</b><span class="muted clip" style="display:block">${esc(nome)}</span></span>`;
 let l,cols,heads,rows,flt;
 if(T.dt==='usuarios'){l=DU.filter(u=>m(u)&&(!T.f1||u.sit===T.f1)&&(!T.f2||(T.f2==='s')===u.valido)&&(!T.f3||u.uso===T.f3));cols='minmax(150px,1.2fr) 120px 80px minmax(190px,1.4fr) 128px 76px 80px 80px 80px 80px 84px';heads=['Usuário','Situação','Válido','Uso do app','Último apontamento','Dias sem apontar','Ordens enviadas','Recebidas','Pendentes','Fora da janela','Retornos pendentes'];
  rows=l.map(u=>[uCell(u.id,u.nome),u.sit==='Pendente'?badge('Pendente','#FDEBDD','#A8420A'):badge('Sem pendência','#E1F3E8','#1D6B3E'),u.valido?'Sim':'Não',`<span class="two" style="font-size:13px">${u.uso}</span>`,`<span class="num-cell" style="font-size:13px">${u.ult?fdt(u.ult):'—'}</span>`,u.dias??'—',u.env,u.rec,u.pend,u.fj,u.ret]);
  flt=sel('saF1',[['Pendente','Pendente'],['Sem pendência','Sem pendência']],T.f1,'Situação: todas')+sel('saF2',[['s','Sim'],['n','Não']],T.f2,'Usuário válido: todos')+sel('saF3',USO_K,T.f3,'Uso do app: todos')}
 else if(T.dt==='ordens'){l=DO.filter(o=>m(o)&&(!T.f1||o.resp===T.f1));cols='110px minmax(150px,1.1fr) minmax(260px,2fr) 100px 130px 90px';heads=['Ordem','Usuário','Motivo','Tratar com','Enviada em','Tentativas'];
  rows=l.map(o=>[ORDENS.some(x=>x.codigo===o.ordem)?`<button class="link num-cell" data-act="ord" data-k="${o.ordem}">${o.ordem}</button>`:`<span class="num-cell">${o.ordem}</span>`,uCell(o.usuario,o.nome),`<span class="two" style="font-size:13px">${esc(o.motivo)}</span>`,o.resp==='TI'?badge('TI','#F1F1F6','#4A4E6A'):badge('Negócio','#FDEBDD','#A8420A'),`<span class="num-cell" style="font-size:13px">${fdt(o.enviada)}</span>`,o.tent]);
  flt=sel('saF1',[['Negócio','Negócio'],['TI','TI']],T.f1,'Tratar com: todos')}
 else{l=DR.filter(r=>m(r)&&(!T.f1||r.motivo===T.f1));cols='130px minmax(150px,1.1fr) minmax(150px,1fr) minmax(220px,1.6fr) minmax(170px,1.2fr) 130px';heads=['Ordem / op.','Usuário','Evento','Motivo','Mensagem do SAP','Pendente desde'];
  rows=l.map(r=>[`<span class="num-cell">${r.ordem} / ${r.op}</span>`,uCell(r.usuario,r.nome),`<span class="two" style="font-size:13px">${esc(r.tipo)}</span>`,`<span class="two" style="font-size:13px">${esc(r.motivo)}</span>`,`<span class="two" style="font-size:13px">${esc(r.msg)}</span>`,`<span class="num-cell" style="font-size:13px">${fdt(r.desde)}</span>`]);
  flt=sel('saF1',DB.motivosRet.map(x=>[x[0],x[0].split(':')[0]]),T.f1,'Motivo: todos')}
 return`<section class="card t-card" id="saTab"><div class="t-head">${tabsH([['usuarios','Usuários',DU.length],['ordens','Ordens pendentes',DO.length],['retornos','Retornos pendentes',DR.length]],T.dt,'saDt')}</div>
 <div class="sa-flt"><input class="inp" id="saQ" placeholder="Buscar em todas as colunas" value="${esc(T.q)}">${flt}<button class="btn btn-g btn-sm" data-act="saFClear">${ic('reset',16)}Limpar</button><span class="muted">${l.length} de ${T.dt==='usuarios'?DU.length:T.dt==='ordens'?DO.length:DR.length} linhas</span></div>
 <div class="t-scroll sa-scroll"><div class="t-min" style="--min:${T.dt==='usuarios'?1260:1000}px;--cols:${cols}"><div class="cols thead">${heads.map((h,i)=>`<span${i>=5&&T.dt==='usuarios'?' style="text-align:right"':''}>${h}</span>`).join('')}</div>${rows.map(r=>`<div class="tr-wrap"><div class="cols tr">${r.map((c,i)=>`<span${i>=5&&T.dt==='usuarios'?' class="num-cell" style="text-align:right"':''} style="min-width:0">${c}</span>`).join('')}</div></div>`).join('')||vazio('Nenhuma linha encontrada','Ajuste a busca ou os filtros.')}</div></div></section>`}
function saHistorico(){const lab=d=>`<span class="hm-d">${['dom','seg','ter','qua','qui','sex','sáb'][d.getDay()]}</span><b>${pad(d.getDate())}</b>`,nomes=perguntas().map(q=>q.n+'  '+q.t);
 const cell=(s,i,t)=>`<span class="hm-c hm-${s}${i===6?' hoje':''}" data-tip="${esc(t+'\n'+fd(HIST_DIAS[i])+': '+SA_ST[s][0])}"></span>`;
 const linha=(t,arr,b)=>`<div class="hm-row"><span class="hm-l${b?' b':''}" title="${esc(t)}">${esc(t)}</span>${arr.map((s,i)=>cell(s,i,t)).join('')}<span class="hm-ok">${arr.filter(s=>s==='ok').length}/7</span></div>`;
 return`<section class="card c-pad"><h2 class="bar-t">Respostas por dia ${infoI('Resultado de cada pergunta da rotina nos últimos 7 dias. O dia de hoje está destacado.')}</h2><p class="c-sub">7 dias · mais recente à direita</p><div class="t-scroll"><div class="hm"><div class="hm-row hm-h"><span></span>${HIST_DIAS.map((d,i)=>`<span class="${i===6?'hoje-t':''}">${lab(d)}</span>`).join('')}<span class="hm-ok muted">OK</span></div>${linha('Veredito do dia',HIST.veredito,1)}<div class="hm-sep"></div>${HIST.q.map((a,i)=>linha(nomes[i],a)).join('')}</div></div>
 <div class="legend" style="margin-top:12px"><span><em style="background:#2E9A5E"></em>OK</span><span><em style="background:#E8A33B"></em>Atenção</span><span><em style="background:#C8341F"></em>Crítico</span><span><em class="hm-nd-l"></em>Sem dados</span></div></section>
 <div class="charts">${HIST.series.map(([t,v,info,un])=>trendCard(t,v,info,un)).join('')}</div>`}
function trendCard(t,v,info,un){const vals=v.filter(x=>x!==null),last=v[6],prev=v[5],mn=Math.min(...vals),mx=Math.max(...vals),md=Math.round(vals.reduce((a,b)=>a+b,0)/vals.length),d=last-prev;
 const W=420,H=190,b=26,top=30,ih=H-b-top,bw=40,gap=(W-7*bw)/8,Y=x=>H-b-ih*x/(mx||1);
 const svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(t)} nos últimos 7 dias">${v.map((x,i)=>{const X=gap+i*(bw+gap),dl=pad(HIST_DIAS[i].getDate())+'/'+pad(HIST_DIAS[i].getMonth()+1);if(x===null)return`<rect x="${X}" y="${H-b-4}" width="${bw}" height="4" fill="url(#hatch)"/><text x="${X+bw/2}" y="${H-8}" text-anchor="middle" font-size="11" fill="#5E627C">${dl}</text><rect class="hb" x="${X}" y="${top}" width="${bw}" height="${ih}" data-tip="${dl}: sem dados"/>`;const h=Math.max(2,H-b-Y(x));return`<path d="${roundTop(X,H-b-h,bw,h)}" fill="${i===6?'#E8641A':'#E3E4EC'}"/>${i<6?`<text x="${X+bw/2}" y="${H-b-h-6}" text-anchor="middle" font-size="11" font-weight="600" fill="#3F4260">${nf(x)}</text>`:''}<text x="${X+bw/2}" y="${H-8}" text-anchor="middle" font-size="11" fill="${i===6?'#A8420A':'#5E627C'}" font-weight="${i===6?700:400}">${dl}</text><rect class="hb" x="${X}" y="${top}" width="${bw}" height="${ih}" data-tip="${dl}: ${nf(x)}${un}"/>`}).join('')}
 <line x1="0" x2="${W}" y1="${Y(md)}" y2="${Y(md)}" stroke="#8B8FA6" stroke-dasharray="4 4"/><text x="2" y="${Y(md)-5}" font-size="11" fill="#5E627C">média ${nf(md)}</text>
 <rect x="${gap+6*(bw+gap)+bw/2-26}" y="${Y(last)-24}" width="52" height="19" rx="6" fill="#1B1A4A"/><text x="${gap+6*(bw+gap)+bw/2}" y="${Y(last)-10}" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">${nf(last)}</text>
 <defs><pattern id="hatch" width="4" height="4" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="2" height="4" fill="#C9CBD6"/></pattern></defs></svg>`;
 return`<section class="card c-pad chart"><h2 class="bar-t">${esc(t)} ${infoI(info)}</h2><div style="display:flex;align-items:baseline;gap:10px;margin-top:8px;flex-wrap:wrap"><span style="font-size:30px;font-weight:800">${nf(last)}${un?`<small style="font-size:14px;color:#5E627C">${un}</small>`:''}</span><span style="font-size:13px;font-weight:700;color:${d>0?'#A8420A':d<0?'#1D6B3E':'#5E627C'}">${d>0?'▲ '+nf(d):d<0?'▼ '+nf(-d):'igual a ontem'}${d?' vs. dia anterior':''}</span></div><p class="muted" style="margin:4px 0 0">Mín. <b>${nf(mn)}</b> &nbsp; Média <b>${nf(md)}</b> &nbsp; Máx. <b>${nf(mx)}</b></p>${svg}</section>`}

