function contaLista(){const txt=$('saCola')?.value||'',nums=new Set([...saLista,...(txt.match(/\d{6,12}/g)||[])]);$('saCnt')&&($('saCnt').textContent=nf(nums.size));return nums}
function lerTexto(t){const linhas=t.split(/\r?\n/).filter(Boolean);if(!linhas.length)return[];const sep=linhas[0].includes(';')?';':linhas[0].includes('\t')?'\t':',',cab=linhas[0].split(sep).map(x=>x.trim().toLowerCase()),io=cab.findIndex(c=>c==='ordem'),ist=cab.findIndex(c=>/status|mensagem|situa/.test(c));
 if(io<0)return t.match(/\d{6,12}/g)||[];return linhas.slice(1).map(l=>l.split(sep)).filter(c=>ist<0||/ordem enviada com sucesso/i.test(c[ist]||'')).map(c=>(c[io]||'').replace(/\D/g,'')).filter(Boolean)}
function carregaXLSX(){return new Promise((ok,er)=>{if(window.XLSX)return ok(window.XLSX);const s=document.createElement('script');s.src='assets/js/vendor/xlsx.full.min.js';s.integrity='sha512-r22gChDnGvBylk90+2e/ycr3RVrDi8DIOkIGNhJlKfuyQM4tIRAI062MaV8sfjQKYVGjOBaZBOA87z+IhZE9DA==';s.crossOrigin='anonymous';s.onload=()=>ok(window.XLSX);s.onerror=er;document.head.appendChild(s)})}
async function lerArquivo(f){try{if(/\.xlsx$/i.test(f.name)){const X=await carregaXLSX(),wb=X.read(await f.arrayBuffer()),csvT=X.utils.sheet_to_csv(wb.Sheets[wb.SheetNames[0]],{FS:';'});saLista=lerTexto(csvT)}else saLista=lerTexto(await f.text());contaLista();toast(saLista.length?nf(new Set(saLista).size)+' ordens lidas de '+f.name:'Nenhuma ordem encontrada em '+f.name,!saLista.length)}catch(e){toast('Não foi possível ler a planilha aqui. Salve como .csv ou cole os números.',true)}}

