/* --- Atualização automática (Início, Alertas e Diagnóstico) --- */
const AUTO={on:true,seg:30,ult:new Date(),n:0};
const AUTO_VIEWS=['analise','alertas','diag'];
function autoPill(){return`<span class="auto-p on" role="status" title="A tela se atualiza sozinha a cada ${AUTO.seg} s"><span class="auto-dot"></span><span id="autoTxt">${autoTxt()}</span></span>`}
function autoTxt(){const s=Math.round((Date.now()-AUTO.ult)/1e3);return'Atualizado '+(s<5?'agora':s<60?'há '+s+' s':'às '+pad(AUTO.ult.getHours())+':'+pad(AUTO.ult.getMinutes()))}
function tickDados(){const t=new Date();
 const le=EVENTOS.filter(e=>e.status==='LE').sort((a,b)=>a.data-b.data)[0];if(le){le.status=rnd()<.85?'PR':'ER';le.retorno=rint(1,10);if(le.status==='ER'){le.causa=CAUSAS[0];le.msg=CAUSAS[0]+'.'}else le.msg='Confirmação gerada corretamente'}
 const a=APARELHOS.filter(x=>x.rede!=='Sem conexão')[AUTO.n%APARELHOS.length];if(a){a.ultSync=t;a.ultDownload=t}
 if(AUTO.n%3===2){const u=APARELHOS.find(x=>x.rede!=='Sem conexão'&&x.mat==='45231');if(u){const o=ORDENS.find(x=>x.ops.some(p=>p.estado==='andamento'));addEv({origem:'ordem',ref:o?o.codigo:'OS-58226',op:o?o.ops.find(p=>p.estado==='andamento').numero:'0010',tipo:'Confirmação parcial',data:t,user:u.nome,status:'LE',disp:u.id,qual:u.qual});EVENTOS.sort((x,y)=>y.data-x.data)}}
 AUTO.n++}
function autoAtualizar(forcar){AUTO.ult=new Date();tickDados();const ocupado=$('scrim')||(document.activeElement&&document.activeElement.closest&&document.activeElement.closest('#main')&&/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName));
 if(!$('app').hidden&&AUTO_VIEWS.includes(S.view)&&(forcar||!ocupado)){const y=$('main').scrollTop;render();$('main').scrollTop=y}else updBell()}
setInterval(()=>{const el=$('autoTxt');if(el)el.textContent=autoTxt();if(!AUTO.on||document.hidden||$('app').hidden||!AUTO_VIEWS.includes(S.view))return;if(Date.now()-AUTO.ult>=AUTO.seg*1e3)autoAtualizar()},1000);

