/* --- Indicadores de confiabilidade --- */
function vDash(){const D=S.dash||(S.dash={dias:30,centro:'',tab:'geral'});if(!D.tab)D.tab='geral';const tabs=tabsH([['geral','Visão geral'],['conf','Confiabilidade dos equipamentos']],D.tab,'dashTab');
 if(D.tab==='geral'){const h=vDashGeral(),i=h.indexOf('</section>')+10;return h.slice(0,i)+tabs+h.slice(i)}
 return head('dash','Indicadores','Com que frequência os equipamentos da planta falham e quanto tempo levam para voltar a operar, a partir das ordens corretivas executadas pelos inspetores.',`<button class="btn btn-s" data-act="confCsv">${ic('down')}Exportar</button>`)+tabs+dashConf(D)}
function falhasConf(D){const dias=D.dias,fo=o=>!D.centro||o.centro===D.centro;return ORDENS.filter(o=>['PM10','PM03'].includes(o.tipo)&&fo(o)&&(NOW-o.inicio)/DAY<=dias)}
function confEquip(D){const fs=falhasConf(D),horas=D.dias*24,eq={};fs.forEach(o=>{const k=o.local.split(' - ')[1]||o.local;(eq[k]=eq[k]||{nome:k,cod:o.local.split(' - ')[0],f:[]}).f.push(o)});
 return Object.values(eq).map(e=>{const enc=e.f.filter(o=>o.fim&&o.fim>=o.inicio),rep=enc.map(o=>(o.fim-o.inicio)/36e5),mttr=rep.length?rep.reduce((a,b)=>a+b,0)/rep.length:null,tRep=rep.reduce((a,b)=>a+b,0),mtbf=(horas-tRep)/e.f.length,disp=mttr!==null?mtbf/(mtbf+mttr)*100:null,ult=e.f.reduce((m,o)=>o.inicio>m?o.inicio:m,e.f[0].inicio);return Object.assign(e,{n:e.f.length,enc:enc.length,aberto:e.f.length-enc.length,mttr,mtbf,disp,ult})}).sort((a,b)=>b.n-a.n||(b.mttr||0)-(a.mttr||0))}
const fmtH=h=>h===null||h===undefined?'—':h>=48?(h/24).toFixed(1).replace('.',',')+' dias':h.toFixed(1).replace('.',',')+' h';
function dashConf(D){const eqs=confEquip(D),fs=falhasConf(D),enc=fs.filter(o=>o.fim),rep=enc.map(o=>(o.fim-o.inicio)/36e5),mttr=rep.length?rep.reduce((a,b)=>a+b,0)/rep.length:null,horas=D.dias*24*Math.max(1,eqs.length),mtbf=fs.length?(horas-rep.reduce((a,b)=>a+b,0))/fs.length:null,disp=mttr!==null&&mtbf?mtbf/(mtbf+mttr)*100:null,comNota=fs.filter(o=>NOTAS.some(n=>n.ordem===o.codigo&&n.tipo==='M8')).length;
 const kpi=(v,l,i,icn,bg,fg)=>`<div class="tile"><span class="ic" style="background:${bg};color:${fg}">${ic(icn,20)}</span><span class="num" style="font-size:26px">${v}</span><span class="lab">${l} ${infoI(i)}</span></div>`;
 const mxT=Math.max(1,...eqs.map(e=>e.mttr||0));
 return`<section class="card dash-f"><div class="segs" role="group" aria-label="Período">${[30,60,90].map(d=>`<button class="seg${D.dias===d?' on':''}" data-act="dashD" data-k="${d}" aria-pressed="${D.dias===d}">${d} dias</button>`).join('')}</div><label class="fld"><span class="lbl">Centro</span><select class="inp" style="width:240px" data-act-ch="dash" data-k="centro"><option value="">Todos</option>${CENTROS.map(c=>`<option${D.centro===c?' selected':''}>${esc(c)}</option>`).join('')}</select></label></section>
 <section class="card c-pad conf-ctx"><span class="a-ic" style="background:#E9E8F8;color:#5B55C9">${ic('info',18)}</span><div><b>O que esta análise mede</b><p>A confiabilidade dos <b>equipamentos da planta da Ternium</b> (prensas, esteiras, fornos, balanças), não do sistema Mobilidade. Cada ordem corretiva aberta para um equipamento conta como uma falha dele, e o tempo de reparo vai do início da ordem até o encerramento técnico feito pelo inspetor no app.</p></div></section>
 <section class="tiles">${kpi(fs.length,'Falhas de equipamento no período','Ordens corretivas (PM10, de emergência, e PM03) abertas para os equipamentos da planta no período. Cada ordem conta como uma falha do equipamento.','warn','#FBE4E2','#B42318')}${kpi(fmtH(mtbf),'Tempo médio entre falhas do equipamento','MTBF (tempo médio entre falhas). Quanto tempo, em média, o equipamento opera entre uma falha e a próxima. Quanto maior, melhor.','clock','#E1F3E8','#1D6B3E')}${kpi(fmtH(mttr),'Tempo médio de reparo do equipamento','MTTR (tempo médio de reparo). Quanto tempo, em média, o equipamento fica parado em reparo: do início da ordem corretiva até o encerramento técnico (CTEC) feito pelo inspetor. Só ordens já encerradas. Quanto menor, melhor.','sync','#FDEBDD','#D35A12')}${kpi(disp===null?'—':disp.toFixed(2).replace('.',',')+'%','Disponibilidade estimada dos equipamentos','Parte do tempo em que o equipamento esteve disponível para produzir: tempo médio entre falhas dividido pela soma do tempo médio entre falhas com o tempo médio de reparo (MTBF ÷ (MTBF + MTTR)).','check','#E9E8F8','#5B55C9')}</section>
 <div class="two-col"><section class="card c-pad"><h2>Tempo médio de reparo por equipamento</h2><p class="c-sub">Só ordens corretivas encerradas no período.</p>${eqs.filter(e=>e.mttr!==null).length?`<table class="mtx" style="margin-top:12px"><tbody>${eqs.filter(e=>e.mttr!==null).sort((a,b)=>b.mttr-a.mttr).map(e=>`<tr><td style="width:46%;font-weight:500">${esc(e.nome)}</td><td><span class="prog"><span class="bar"><i style="width:${e.mttr/mxT*100}%;background:#E8641A"></i></span><b style="min-width:64px">${fmtH(e.mttr)}</b></span></td></tr>`).join('')}</tbody></table>`:'<p class="muted" style="margin-top:12px">Nenhuma ordem corretiva encerrada no período.</p>'}</section>
 <section class="card c-pad"><h2>Qualidade dos apontamentos nas ordens ${infoI('O cálculo depende de as ordens corretivas registrarem quando o equipamento falhou e quando voltou a operar. Esta seção mostra quanto desses registros está completo.')}</h2><p class="c-sub">Base usada no cálculo.</p>
 <div class="chk-row"><span class="a-ic" style="background:#E1F3E8;color:#1D6B3E">${ic('check',18)}</span><span><span class="a-t">${enc.length} de ${fs.length} ordens corretivas encerradas (com início e fim)</span><span class="a-d">Início = início da ordem; fim = encerramento técnico (CTEC). Entram no tempo de reparo.</span></span></div>
 <div class="chk-row"><span class="a-ic" style="background:#FDF3D0;color:#6B5000">${ic('clock',18)}</span><span><span class="a-t">${fs.length-enc.length} ordens corretivas ainda em aberto</span><span class="a-d">Equipamento ainda em reparo ou ordem não encerrada no app: contam como falha, mas ficam fora do tempo de reparo.</span></span></div>
 <div class="chk-row"><span class="a-ic" style="background:${comNota/(fs.length||1)>=.7?'#E1F3E8':'#FDF3D0'};color:${comNota/(fs.length||1)>=.7?'#1D6B3E':'#6B5000'}">${ic('note',18)}</span><span><span class="a-t">${comNota} de ${fs.length} ordens com nota de manutenção corretiva (M8)</span><span class="a-d">Sem a nota, considera-se que o equipamento falhou quando a ordem foi aberta. Registrar a nota no momento da falha deixa o tempo de reparo mais preciso.</span></span></div>
 ${fs.length<10?`<div class="warn-box" style="margin-top:12px">Poucas falhas de equipamento no período (${fs.length}): use os valores como tendência, não como meta.</div>`:''}</section></div>
 <section class="card t-card"><div class="t-head"><h2>Por equipamento da planta</h2><span class="pill">${eqs.length} ${eqs.length===1?'equipamento':'equipamentos'}</span></div><div class="t-scroll"><div class="t-min" style="--min:1060px;--cols:minmax(200px,1.6fr) 70px 100px 90px 150px 150px 110px 120px"><div class="cols thead"><span>Equipamento</span><span>Falhas</span><span>Ordens encerradas</span><span>Ordens em aberto</span><span>Tempo médio entre falhas ${infoI('MTBF: quanto tempo, em média, o equipamento opera entre uma falha e a próxima.')}</span><span>Tempo médio de reparo ${infoI('MTTR: quanto tempo, em média, o equipamento fica parado em reparo.')}</span><span>Disponib.</span><span>Última falha</span></div>
 ${eqs.map(e=>`<div class="tr-wrap"><div class="cols tr"><span style="min-width:0"><b class="clip" style="display:block;font-weight:600">${esc(e.nome)}</b><span class="muted clip" style="display:block" title="${esc(e.cod)}">${esc(e.cod)}</span></span><span class="num-cell">${e.n}</span><span class="num-cell">${e.enc}</span><span class="num-cell">${e.aberto}</span><span class="num-cell">${fmtH(e.mtbf)}</span><span class="num-cell">${fmtH(e.mttr)}</span><span class="num-cell">${e.disp===null?'—':e.disp.toFixed(2).replace('.',',')+'%'}</span><span class="num-cell" style="font-size:13px">${fd(e.ult)}</span></div></div>`).join('')||vazio('Nenhuma falha de equipamento no período','Amplie o período ou mude o centro.')}</div></div></section>`}

