/* --- Contexto de cada tela: deixa claro se trata da manutenção da planta ou do sistema --- */
const CTX_T={plant:['Manutenção da planta','#FDEBDD','#A8420A','clip'],sis:['Sistema Mobilidade','#E9E8F8','#4B45B5','phone'],adm:['Administração','#F1F1F6','#4A4E6A','badge'],geral:['Visão geral','#DDF0F2','#1A6E78','home']};
const CTX={
analise:['geral','Resumo do dia em dois lados: o trabalho de manutenção na planta (ordens, operações e notas dos inspetores) e o funcionamento do sistema (envios ao SAP e aparelhos). Comece por aqui para ver o que precisa de ação.'],
alertas:['geral','Só consulta: o portal lista os alertas, e a correção é feita fora dele, pelo time técnico, no app ou no SAP. Cada alerta indica a origem: <b>manutenção da planta</b> (emergência não iniciada, ordem atrasada, operação pausada) ou <b>sistema Mobilidade</b> (aparelho sem sincronizar, erro no envio ao SAP, app desatualizado).'],
ordens:['plant','Ordens de manutenção que os inspetores executam nos equipamentos da planta, com as operações de cada uma. Aqui se acompanha o andamento do trabalho e se concluem ordens.'],
notas:['plant','Notas que os inspetores registram sobre problemas encontrados nos equipamentos da planta (inspeção, manutenção corretiva ou solicitação). No SAP, a nota origina ou complementa uma ordem.'],
dash_geral:['plant','Números do trabalho de manutenção no período: ordens abertas e encerradas, horas, desvios nas operações e notas por risco. Só os gráficos de envios ao SAP tratam do sistema: mostram se os apontamentos dos inspetores chegaram ao SAP.'],
eventos:['sis','Cada apontamento feito no app (início, pausa, confirmação de operação, nota) vira um envio ao SAP. Esta tela mostra se ele chegou, está aguardando ou deu erro, para reprocessar. Mede a integração app → SAP, não a manutenção em si.'],
saude:['sis','Verifica todo dia se o sistema Mobilidade está funcionando de ponta a ponta: filas, banco de dados, entrega das ordens aos aparelhos, retorno dos apontamentos e login. Não avalia os equipamentos da planta nem o trabalho dos inspetores.'],
reportes:['sis','Problemas no app relatados pelos próprios inspetores (erro na tela, ordem que não aparece, apontamento que não vai). O suporte classifica, trata e responde. São falhas do sistema, não dos equipamentos.'],
diag:['sis','Investiga o aparelho de um inspetor: versão do app, sincronização, qualidade da rede e envios ao SAP. Use quando alguém diz que a ordem não chegou ao celular ou que o apontamento não foi para o SAP.'],
versoes:['sis','Versão do app Mobilidade instalada no celular de cada inspetor. Cada versão nova vai primeiro para o grupo beta e, depois de validada, para os demais usuários; cada grupo tem a sua versão liberada e a sua versão mínima.'],
perfis:['adm','Quem pode usar o app e o portal, e o que cada perfil (Inspetor, Coordenador, Administrador) pode ver ou alterar.'],
auditoria:['adm','Registro de quem fez o quê no portal e no app (concluiu ordem, reprocessou envio, mudou perfil). Serve para conferência e não pode ser alterado.']};
function ctxCard(k){const c=CTX[k];if(!c)return'';const[tl,bg,fg,icn]=CTX_T[c[0]];return`<section class="card ctx"><span class="ctx-tag" style="background:${bg};color:${fg}">${ic(icn,14)}${tl}</span><p>${c[1]}</p></section>`}
function comCtx(h){const k=S.view==='dash'?(S.dash&&S.dash.tab==='conf'?'':'dash_geral'):S.view,c=ctxCard(k);if(!c)return h;const i=h.indexOf('</section>');return i<0?h:h.slice(0,i+10)+c+h.slice(i+10)}
const AL_ORIG={emerg:'plant',pausa:'plant',prazo:'plant',semResp:'plant'};
const alOrig=r=>{const[tl,bg,fg]=CTX_T[AL_ORIG[r]||'sis'];return`<span class="ctx-tag sm" style="background:${bg};color:${fg}">${tl}</span>`};

