/* filtro de usuários no modal do grupo beta */
function betaFiltro(){const s=$('scrim');if(!s)return;const q=s.querySelector('#btQ'),so=s.querySelector('#btSo'),its=[...s.querySelectorAll('.beta-i')],nrm=x=>x.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
 const ap=()=>{const t=nrm(q.value.trim());let vis=0;its.forEach(el=>{const ok=(!t||nrm(el.dataset.bq).includes(t))&&(!so.checked||el.querySelector('[data-beta]').checked);el.hidden=!ok;if(ok)vis++});s.querySelector('#btV').hidden=vis>0;const n=s.querySelectorAll('[data-beta]:checked').length;s.querySelector('#btC').textContent=n+(n===1?' usuário no grupo beta':' usuários no grupo beta')+' · mostrando '+vis+' de '+its.length};
 q.addEventListener('input',ap);so.addEventListener('change',ap);s.querySelector('.beta-l').addEventListener('change',ap);ap();setTimeout(()=>q.focus(),50)}

/* --- Significado dos códigos do SAP (fonte: app Mobilidade e levantamento do código do app) --- */
const COD_SIG={PM10:'PM10: ordem de emergência. Ordem não planejada, que também pode ser criada pelo inspetor no próprio app.',M0:'M0: nota de inspeção.',M3:'M3: solicitação de manutenção.',M8:'M8: nota de manutenção corretiva.',INM:'INM: tipo de atividade Inspeção e manutenção. Em ordens PM02 com essa atividade, cada operação só é liberada depois que a anterior é finalizada.',CRNT:'CRNT: confirmação final da operação. Registra no SAP que a operação terminou.',CTEC:'CTEC: encerramento técnico da ordem. A ordem passa ao status I0045 (encerrada tecnicamente) no SAP.'};
function codI(c){return COD_SIG[c]?infoI(COD_SIG[c]):''}
function evTipoI(t){const m=String(t).match(/\((CRNT|CTEC)\)/);return m?infoI(COD_SIG[m[1]]):''}
function ativI(o,html){return /^INM\b/.test(o.ativ||'')?html.replace('<span>Tipo de atividade</span>','<span>Tipo de atividade '+infoI(COD_SIG.INM)+'</span>'):html}

