Object.assign(ACT,{
 alLer:b=>{const k=b.dataset.k,lido=LIDOS.has(k);lido?LIDOS.delete(k):LIDOS.add(k);salvaLidos();toast(lido?'Alerta marcado como não lido':'Alerta marcado como lido');render()},
 alLerTodos:()=>{const T=S.al,l=alertas().filter(a=>(!T.sev||a.sev===T.sev)&&!LIDOS.has(a.id));l.forEach(a=>LIDOS.add(a.id));salvaLidos();toast(l.length+(l.length===1?' alerta marcado como lido':' alertas marcados como lidos'));render()},
 alVer:b=>{S.al.ver=b.dataset.k;render()}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-lido]');if(el&&!LIDOS.has(el.dataset.lido)){LIDOS.add(el.dataset.lido);salvaLidos();updBell()}},true);

