Object.assign(ES,{'Ordens em aberto por centro de trabalho':'Órdenes abiertas por puesto de trabajo','Tempo médio entre falhas do equipamento':'Tiempo medio entre fallas del equipo','Tempo médio de reparo do equipamento':'Tiempo medio de reparación del equipo','Tempo médio entre falhas':'Tiempo medio entre fallas','Tempo médio de reparo':'Tiempo medio de reparación','MTBF (tempo médio entre falhas). Quanto tempo, em média, o equipamento opera entre uma falha e a próxima. Quanto maior, melhor.':'MTBF (tiempo medio entre fallas). Cuánto tiempo, en promedio, opera el equipo entre una falla y la siguiente. Cuanto mayor, mejor.','MTTR (tempo médio de reparo). Quanto tempo, em média, o equipamento fica parado em reparo: do início da ordem corretiva até o encerramento técnico (CTEC) feito pelo inspetor. Só ordens já encerradas. Quanto menor, melhor.':'MTTR (tiempo medio de reparación). Cuánto tiempo, en promedio, el equipo queda detenido en reparación: desde el inicio de la orden correctiva hasta el cierre técnico (CTEC) del inspector. Solo órdenes cerradas. Cuanto menor, mejor.','Parte do tempo em que o equipamento esteve disponível para produzir: tempo médio entre falhas dividido pela soma do tempo médio entre falhas com o tempo médio de reparo (MTBF ÷ (MTBF + MTTR)).':'Parte del tiempo en que el equipo estuvo disponible para producir: tiempo medio entre fallas dividido por la suma del tiempo medio entre fallas y el tiempo medio de reparación (MTBF ÷ (MTBF + MTTR)).','MTBF: quanto tempo, em média, o equipamento opera entre uma falha e a próxima.':'MTBF: cuánto tiempo, en promedio, opera el equipo entre una falla y la siguiente.','MTTR: quanto tempo, em média, o equipamento fica parado em reparo.':'MTTR: cuánto tiempo, en promedio, el equipo queda detenido en reparación.','Processado':'Procesado','Reenvio pendente':'Reenvío pendiente','Aguardando retorno do SAP':'Esperando respuesta de SAP','Processados nas últimas 24 h':'Procesados en las últimas 24 h','Com erro no SAP':'Con error en SAP'});
ES_F.unshift([/^Sigla (\w+): (.+)\.$/,(m,s,d)=>'Sigla '+s+': '+({'aguardando envio':'esperando envío','reenvio pendente':'reenvío pendiente','aguardando retorno do SAP':'esperando respuesta de SAP','processado pelo SAP':'procesado por SAP','processado pelo SAP após reenvio':'procesado por SAP tras reenvío','erro no SAP':'error en SAP'}[d]||d)+'.']);
Object.assign(ES,{'PM10: ordem de emergência. Ordem não planejada, que também pode ser criada pelo inspetor no próprio app.':'PM10: orden de emergencia. Orden no planificada, que el inspector también puede crear en la propia app.','M0: nota de inspeção.':'M0: aviso de inspección.','M3: solicitação de manutenção.':'M3: solicitud de mantenimiento.','M8: nota de manutenção corretiva.':'M8: aviso de mantenimiento correctivo.','INM: tipo de atividade Inspeção e manutenção. Em ordens PM02 com essa atividade, cada operação só é liberada depois que a anterior é finalizada.':'INM: tipo de actividad Inspección y mantenimiento. En órdenes PM02 con esta actividad, cada operación se libera solo después de finalizada la anterior.','CRNT: confirmação final da operação. Registra no SAP que a operação terminou.':'CRNT: confirmación final de la operación. Registra en SAP que la operación terminó.','CTEC: encerramento técnico da ordem. A ordem passa ao status I0045 (encerrada tecnicamente) no SAP.':'CTEC: cierre técnico de la orden. La orden pasa al estado I0045 (cerrada técnicamente) en SAP.'});
